head.script:
scwin.screenId = "jldfil40300";

///////// 1. 변수 및 선언 영역 /////////

scwin.isurCdTitle = '';


///////// 2. 초기화 영역 /////////

// [A] 초기 목록 미해결 — jldfil40300: 진입 키 findid 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil40300.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_corpUsrTpCd_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_corpUsrTpCd_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_corpUsrTpCd_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.chgCorpUsrTpCd()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40300.slc_corpUsrTpCd_onchange' }); }
};

/**
 * @event
 * @name scwin.slc_selEmail_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_selEmail_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_selEmail_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        ((s, t) => { if (t && t.setValue) { t.setValue((s && s.getValue) ? s.getValue() : ""); } const i = (s && typeof s.getSelectedIndex === "function") ? s.getSelectedIndex() : -1; if (i === 0 && t && t.focus) { t.focus(); } })($c.util.getComponent("slc_selEmail"), $c.util.getComponent('ipt_apctEmail2'));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40300.slc_selEmail_onchange' }); }
};

/**
 * @event
 * @name scwin.btn_Confirm_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Confirm_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Confirm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.confirm()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40300.btn_Confirm_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: "/register/findId.do",
        ref: "dma_ConfirmReq",
        target: "dlt_codeVOList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil40300.tx_fn_Confirm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.confirm = async function () {
    /* sdd-asis-lifecycle:begin fn_Confirm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.findIdForm || { elements: [] });
    $("#slc_corpUsrTpCd").attr("alt", "사용자1");
    if ($c.cm.fn_NullChk($("#slc_corpUsrTpCd").get(0))) {
        return;
    }
    if ($c.cm.fn_IsNull($c.util.getComponent('ipt_isurCd'), scwin.isurCdTitle.replace('\n', ' '))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_bzRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_bzRegNo').getValue().length != 10) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_bzRegNo')) + '는 10자리입니다.');
        $c.util.getComponent("ipt_bzRegNo").focus();
        return;
    }
    if (!($c.cm.fn_IsNumber($c.util.getComponent('ipt_bzRegNo')))) {
        await $c.win.alert('사업자등록번호는 숫자만 입력하세요');
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_apctNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "신청자"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_apctNm'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_apctEmail1')) || $c.cm.fn_NullChk($c.util.getComponent('ipt_apctEmail2'))) {
        return;
    }
    $c.util.getComponent('dma_ConfirmReq').set('apctEmail', $c.str.trim($c.util.getComponent('ipt_apctEmail1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_apctEmail2').getValue()));
    if (!$c.cm.fn_CheckEmail($c.util.getComponent('dma_ConfirmReq').get('apctEmail'))) {
        return;
    }
    $c.util.getComponent('dma_ConfirmReq').set('method', 'registerIDIssueInformation');
    frm.action = 'findId.do';
    { const nr = await scwin.tx_fn_Confirm(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil40301/jldfil40301.xml", { "method": 'registerIDIssueInformation' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chgCorpUsrTpCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chgCorpUsrTpCd = function () {
    /* sdd-asis-lifecycle:begin fn_ChgCorpUsrTpCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.findIdForm || { elements: [] });
    const corpUsrTpCd = $c.util.getComponent('slc_corpUsrTpCd').getValue();
    let inputDisplayVal = '';
    if (corpUsrTpCd === '14') {
        scwin.isurCdTitle = '대상회사코드(5자리)';
        inputDisplayVal = 'inline';
    } else {
        if (corpUsrTpCd === '22') {
            scwin.isurCdTitle = '회원고유코드';
            inputDisplayVal = 'none';
        } else {
            scwin.isurCdTitle = '회사코드(5자리)';
            if (corpUsrTpCd === '11' || corpUsrTpCd === '12' || corpUsrTpCd === '21') {
                inputDisplayVal = 'none';
            } else {
                if (corpUsrTpCd === '15' || corpUsrTpCd === '23') {
                    inputDisplayVal = 'inline';
                } else {
                    inputDisplayVal = 'none';
                }
            }
        }
    }
    ($c.util.getComponent('txt_isurCdTitle') && $c.util.getComponent('txt_isurCdTitle').setValue) ? $c.util.getComponent('txt_isurCdTitle').setValue(scwin.isurCdTitle) : (($c.util.getComponent('txt_isurCdTitle') && $c.util.getComponent('txt_isurCdTitle').setText) ? $c.util.getComponent('txt_isurCdTitle').setText(scwin.isurCdTitle) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'txt_isurCdTitle'), void (scwin.isurCdTitle)));
    /* sdd-asis-lifecycle:end */
};
